export const parameters = [
  { code: "NO3", name: "Nitrates", unit: "mg/L", legal_limit: 10 },
  { code: "PO4", name: "Phosphates", unit: "mg/L", legal_limit: 0.2 },
  { code: "EC", name: "Escherichia coli", unit: "MPN/100mL", legal_limit: 500 },
  { code: "PB", name: "Lead", unit: "µg/L", legal_limit: 10 },
  { code: "DO", name: "Dissolved Oxygen", unit: "mg/L", legal_limit: null }
];

const seed = (stationId) => {
  let s = 0;
  for (let i = 0; i < stationId.length; i++) s = (s * 31 + stationId.charCodeAt(i)) >>> 0;
  return () => {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    return s / 0x7fffffff;
  };
};

export function generateMeasurements(stationId) {
  const rng = seed(stationId);
  const out = [];
  const now = Date.now();
  for (const p of parameters) {
    const baseline = {
      NO3: 6, PO4: 0.15, EC: 300, PB: 5, DO: 8
    }[p.code];
    const spread = { NO3: 3, PO4: 0.1, EC: 200, PB: 3, DO: 1.5 }[p.code];
    for (let i = 11; i >= 0; i--) {
      const d = new Date(now - i * 30 * 24 * 3600 * 1000);
      const value = Math.max(0, baseline + (rng() - 0.5) * 2 * spread);
      out.push({
        station_id: stationId,
        param_code: p.code,
        param_name: p.name,
        unit: p.unit,
        legal_limit: p.legal_limit,
        value: Number(value.toFixed(2)),
        timestamp: d.toISOString().slice(0, 10)
      });
    }
  }
  return out;
}